#nullable enable // autogenerated


using MVZ2.GameContent.Contraptions;
using MVZ2.Vanilla.Grids;
using MVZ2Logic;
using PVZEngine;
using PVZEngine.Entities;
using PVZEngine.Grids;
using PVZEngine.Placements;

namespace MVZ2.GameContent.Placements
{
    public class DrivenserPlaceMethod : PlaceMethod
    {
        public override NamespaceID? GetPlaceError(PlacementDefinition placement, LawnGrid grid, EntityDefinition entity)
        {
            using var gridEntities = grid.GetEntitiesDisposeable();
            var entities = gridEntities.Value;
            if (entities.Count <= 0)
            {
                return VanillaGridStatus.onlyUpgrade;
            }
            bool canUpgrade = false;
            foreach (var ent in entities)
            {
                if (Drivenser.CanUpgrade(ent) || EXPANDispenser_Drivenser.CanUpgrade(ent))
                {
                    canUpgrade = true;
                    break;
                }
            }
            if (!canUpgrade)
            {
                return VanillaGridStatus.onlyUpgrade;
            }
            return null;
        }

        public override PlaceOutput PlaceEntity(PlacementDefinition placement, LawnGrid grid, EntityDefinition entity, PlaceParams param)
        {
            using var gridEntities = grid.GetEntitiesDisposeable();
            Entity? target = null;
            foreach (var ent in gridEntities.Value)
            {
                if (Drivenser.CanUpgrade(ent) || EXPANDispenser_Drivenser.CanUpgrade(ent))
                {
                    target = ent;
                }
            }
            if (target == null)
                return PlaceOutput.InvalidOutput;
            // 驱动发射器本体升挡；万象天枢_驱动融合体同样通过叠卡升挡
            if (target.IsEntityOf(VanillaContraptionID.drivenser))
                Drivenser.Upgrade(target);
            else
                EXPANDispenser_Drivenser.Upgrade(target);
            return new PlaceOutput(target, entity)
            {
                increaseTakenConveyorSeed = true,
            };
        }
    }
}
